import path from 'node:path';

const GENERATED_HEADER = `// AUTO-GENERATED BY create-fullstack-feature
// DO NOT EDIT MANUALLY`;

const BASE_GENERATED_ROUTES = `${GENERATED_HEADER}

import type { Routes } from "@angular/router";

export const generatedWebsiteRoutes: Routes = [
];

export const generatedDashboardRoutes: Routes = [
];
`;

const BASE_DASHBOARD_NAV = `${GENERATED_HEADER}

export type DashboardNavItem = {
  labelKey: string;
  label: string;
  path: string;
};

export const generatedDashboardNav: DashboardNavItem[] = [
];
`;

/**
 * Idempotently register a feature's lazy routes inside
 * `Client/src/app/router/generated-routes.ts`.
 *
 * @param {object} config
 * @param {string} [existingContents]
 * @returns {{ relativePath: string, contents: string }}
 */
export function buildAngularGeneratedRoutes(config, existingContents) {
  const { kebabName, kebabPluralName, camelName } = config.feature;
  const surface = config.surface ?? { dashboard: true, public: false };

  let contents =
    existingContents && existingContents.trim().length > 0
      ? existingContents
      : BASE_GENERATED_ROUTES;

  const importPath = `../features/${kebabPluralName}/${kebabName}.routes`;
  const entry = `  {
    path: "${kebabPluralName}",
    loadChildren: () =>
      import("${importPath}").then((m) => m.${camelName}Routes),
  },
`;

  if (surface.public) {
    contents = insertBeforeArrayClose(
      contents,
      'export const generatedWebsiteRoutes: Routes = [',
      entry,
      importPath,
    );
  }

  if (surface.dashboard) {
    contents = insertBeforeArrayClose(
      contents,
      'export const generatedDashboardRoutes: Routes = [',
      entry,
      importPath,
    );
  }

  return {
    relativePath: path.join(
      'Client',
      'src',
      'app',
      'router',
      'generated-routes.ts',
    ),
    contents,
  };
}

/**
 * Idempotently register a feature's dashboard navigation entry inside
 * `Client/src/app/navigation/generated-dashboard-nav.ts`.
 *
 * @param {object} config
 * @param {string} [existingContents]
 * @returns {{ relativePath: string, contents: string }}
 */
export function buildAngularDashboardNav(config, existingContents) {
  const { kebabPluralName, camelPluralName } = config.feature;
  const surface = config.surface ?? { dashboard: true, public: false };
  const label = config.labels?.enPlural ?? config.feature.pluralName;

  let contents =
    existingContents && existingContents.trim().length > 0
      ? existingContents
      : BASE_DASHBOARD_NAV;

  if (surface.dashboard) {
    const navPath = `/dashboard/${kebabPluralName}`;
    const entry = `  {
    labelKey: "nav.${camelPluralName}",
    label: "${label}",
    path: "${navPath}",
  },
`;
    contents = insertBeforeArrayClose(
      contents,
      'export const generatedDashboardNav: DashboardNavItem[] = [',
      entry,
      `path: "${navPath}"`,
    );
  }

  return {
    relativePath: path.join(
      'Client',
      'src',
      'app',
      'navigation',
      'generated-dashboard-nav.ts',
    ),
    contents,
  };
}

/**
 * Insert an entry before the closing `];` of a named array declaration, unless
 * the array already contains the dedupe token.
 *
 * @param {string} contents
 * @param {string} declaration
 * @param {string} entry
 * @param {string} token
 */
function insertBeforeArrayClose(contents, declaration, entry, token) {
  const start = contents.indexOf(declaration);
  if (start === -1) {
    return contents;
  }

  const closeIndex = contents.indexOf('];', start);
  if (closeIndex === -1) {
    return contents;
  }

  const body = contents.slice(start, closeIndex);
  if (body.includes(token)) {
    return contents;
  }

  const before = contents.slice(0, closeIndex);
  const after = contents.slice(closeIndex);
  const separator = before.endsWith('\n') ? '' : '\n';
  return `${before}${separator}${entry}${after}`;
}
